<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';require_login();
if(!has_permission('reports.view')&&!has_permission('financial_reports.view')&&!has_permission('pharmacy.reports')&&!has_permission('inventory.reports')){http_response_code(403);exit('Reports access is not assigned to your account.');}
$cards=[];
if(has_permission('reports.view')){$cards=[['Registered patients',(int)$pdo->query('SELECT COUNT(*) FROM patients')->fetchColumn()],['Appointments today',(int)$pdo->query("SELECT COUNT(*) FROM appointments WHERE DATE(scheduled_at)=CURDATE() AND status<>'cancelled'")->fetchColumn()],['Active admissions',(int)$pdo->query("SELECT COUNT(*) FROM admissions WHERE status='admitted'")->fetchColumn()],['Lab tests awaiting results',(int)$pdo->query("SELECT COUNT(*) FROM lab_tests WHERE status IN ('requested','in_progress')")->fetchColumn()],['Imaging awaiting reports',(int)$pdo->query("SELECT COUNT(*) FROM radiology_requests WHERE status IN ('requested','in_progress')")->fetchColumn()],['Low-stock inventory items',(int)$pdo->query('SELECT COUNT(*) FROM inventory WHERE quantity<=reorder_level')->fetchColumn()]];}
$revenue=null;$outstanding=null;if(has_permission('financial_reports.view')){$revenue=(float)$pdo->query('SELECT COALESCE(SUM(amount),0) FROM payments WHERE DATE(paid_at)=CURDATE()')->fetchColumn();$outstanding=(float)$pdo->query("SELECT COALESCE(SUM(i.total_amount-COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.invoice_id=i.id),0)),0) FROM invoices i WHERE i.status IN ('unpaid','partial')")->fetchColumn();}
$work=[];if(has_permission('reports.view')){$work=$pdo->query('SELECT DATE(created_at) AS day,COUNT(*) AS total FROM patients WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 6 DAY) GROUP BY DATE(created_at) ORDER BY day DESC')->fetchAll();}
$lowStock=[];if(has_permission('inventory.reports')){$lowStock=$pdo->query('SELECT item_name,category,quantity,reorder_level,unit FROM inventory WHERE quantity<=reorder_level ORDER BY category,item_name')->fetchAll();}
$pharmacyStock=[];if(has_permission('pharmacy.reports')){$pharmacyStock=$pdo->query('SELECT name,sku,quantity,reorder_level,unit FROM medicines WHERE quantity<=reorder_level ORDER BY name')->fetchAll();}
$pageTitle='Hospital reports';require __DIR__.'/../includes/header.php';?>
<div class="page-heading"><div><h2>Hospital reports</h2><p>Operational activity and service queues across the hospital.</p></div><button class="btn btn-outline-secondary" onclick="window.print()">Print</button></div>
<?php if($cards):?><div class="row g-3 mb-3"><?php foreach($cards as [$label,$value]):?><div class="col-6 col-xl-4"><article class="stat-card"><div class="stat-label"><?=e($label)?></div><div class="stat-value"><?=number_format($value)?></div><div class="stat-note">Current system count</div></article></div><?php endforeach;?></div><?php endif;?>
<?php if($revenue!==null):?><section class="content-card"><div class="card-heading"><h3>Financial overview</h3></div><div class="row p-3"><div class="col-md-6"><div class="stat-label">Payments received today</div><div class="stat-value"><?=number_format($revenue,2)?></div></div><div class="col-md-6"><div class="stat-label">Outstanding invoice balance</div><div class="stat-value"><?=number_format($outstanding,2)?></div></div></div></section><?php endif;?>
<?php if($work):?><section class="content-card"><div class="card-heading"><h3>Recent patient registrations</h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Patients registered</th></tr></thead><tbody><?php foreach($work as $row):?><tr><td><?=e(date('M j, Y',strtotime($row['day'])))?></td><td><?= (int)$row['total']?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
<?php if(has_permission('inventory.reports')):?><section class="content-card"><div class="card-heading"><h3>Inventory reorder list</h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Item</th><th>Category</th><th>In stock</th><th>Reorder at</th></tr></thead><tbody><?php if(!$lowStock):?><tr><td class="empty-state" colspan="4">No items are below their reorder level.</td></tr><?php else:foreach($lowStock as $item):?><tr><td><?=e($item['item_name'])?></td><td><?=e($item['category'])?></td><td><?= (int)$item['quantity']?> <?=e($item['unit'])?></td><td><?= (int)$item['reorder_level']?> <?=e($item['unit'])?></td></tr><?php endforeach;endif;?></tbody></table></div></section><?php endif;?>
<?php if(has_permission('pharmacy.reports')):?><section class="content-card"><div class="card-heading"><h3>Medicine reorder list</h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Medicine</th><th>SKU</th><th>In stock</th><th>Reorder at</th></tr></thead><tbody><?php if(!$pharmacyStock):?><tr><td class="empty-state" colspan="4">No medicines are below their reorder level.</td></tr><?php else:foreach($pharmacyStock as $item):?><tr><td><?=e($item['name'])?></td><td><?=e($item['sku'])?></td><td><?= (int)$item['quantity']?> <?=e($item['unit'])?></td><td><?= (int)$item['reorder_level']?> <?=e($item['unit'])?></td></tr><?php endforeach;endif;?></tbody></table></div></section><?php endif;?>
<p class="subtle">Report totals reflect records currently stored in the system. Detailed clinical analytics and insurance reporting are not included.</p>
<?php require __DIR__.'/../includes/footer.php';?>
